post_run_integrity.exact_source_diff:
--- v3-source/game/cnc_eyes.cpp
+++ canonical/game/cnc_eyes.cpp
@@ -1415,9 +1415,13 @@

 static float fx_terrain_shadow_strength(void)
 {
-    if (fx_desert_terrain()) return g_fx.desert_shadow_strength;
-    if (fx_snow_terrain()) return g_fx.snow_shadow_strength;
-    if (g_fxActive && !g_fx.dos_classic && !strcmp(g_pack.theater,"SAND")) return g_fx.sand_shadow_strength;
+    /* Shadow-map admission runs before world_begin sets g_fxActive. Selection must
+       depend on the loaded theater, not on which render pass is currently active. */
+    if (!g_fx.dos_classic) {
+        if (!strcmp(g_pack.theater,"DESERT")) return g_fx.desert_shadow_strength;
+        if (!strcmp(g_pack.theater,"SNOW") || !strcmp(g_pack.theater,"RASNOW")) return g_fx.snow_shadow_strength;
+        if (!strcmp(g_pack.theater,"SAND")) return g_fx.sand_shadow_strength;
+    }
     return g_fx.terrain_shadow_strength;
 }
